#!/usr/bin/python3
import sys
import requests
import hashlib

# Constants from the challenge definition
L = 2 ** 252 + 27742317777372353535851937790883648493
T = 24

def _coeffs():
    # Recreate the deterministic higher-order coefficients generated by the server
    # Note: _C0 and _C1 are unknown, but c_2 through c_T are publicly reproducible via static hashing.
    h = hashlib.sha256(b"quorum/ledger/v1").digest()
    c_known = []
    for _ in range(2, T + 1):
        h = hashlib.sha256(h).digest()
        c_known.append(int.from_bytes(h, "big") % L)
    return c_known

def solve(target_ip):
    base_url = f"http://{target_ip}:23000"
    print(f"[*] Targeting {base_url}...")

    # Step 1: Fetch parameters
    resp = requests.get(f"{base_url}/params")
    if resp.status_code != 200:
        print("[-] Failed to fetch /params")
        return
    
    data = resp.json()
    X = [int(x) for x in data["x"]]
    C_sealed = int(data["target"])
    K = int(data["bind"]["K"])
    M = int(data["bind"]["M"])

    # Step 2: Request just 2 shares from /audit (indices 0 and 1)
    print("[*] Requesting shares from /audit...")
    audit_resp = requests.post(f"{base_url}/audit", json={"indices": [0, 1]})
    if audit_resp.status_code != 200:
        print(f"[-] Audit failed: {audit_resp.text}")
        return
    
    shares_data = audit_resp.json()["shares"]
    s0 = int(shares_data["0"])
    s1 = int(shares_data["1"])
    x0 = X[0]
    x1 = X[1]

    # Step 3: Compute known polynomial contributions for indices 0 and 1
    # share(x) = C_0 + C_1*x + sum_{j=2}^T c_j * x^j
    # Let K_val(x) = sum_{j=2}^T c_j * x^j
    c_known = _coeffs()
    
    def evaluate_known(x):
        acc = 0
        # c_known corresponds to powers x^2 up to x^T
        for idx, c in enumerate(c_known):
            power = idx + 2
            acc = (acc + c * pow(x, power, L)) % L
        return acc

    k0 = evaluate_known(x0)
    k1 = evaluate_known(x1)

    # Adjusted shares removing the known polynomial part:
    # y_0 = s0 - k0 = C_0 + C_1 * x0
    # y_1 = s1 - k1 = C_0 + C_1 * x1
    y0 = (s0 - k0) % L
    y1 = (s1 - k1) % L

    # Step 4: Solve the 2x2 linear system over Z_L for C_0 and C_1
    # C_1 = (y0 - y1) * inv(x0 - x1) mod L
    dx = (x0 - x1) % L
    dx_inv = pow(dx, L - 2, L)
    C1 = ((y0 - y1) * dx_inv) % L
    C0 = (y0 - C1 * x0) % L

    print(f"[+] Recovered C0 (Secret Private Key): {C0}")

    # Step 5: Compute the valid response 'z' required by /sign
    # challenge c = challenge_from_sealed()
    # y = (pow(K, L - 2, L) * ((C_SEALED - M) % L)) % L
    # c = (y + T) % L
    # verify(z) checks: ed25519.mult_base(z) == R + c * PK
    # Since PK = mult_base(C0) and R = mult_base(C1),
    # mult_base(z) == mult_base(C1 + c * C0) => z = (C1 + c * C0) % L
    
    y_val = (pow(K, L - 2, L) * ((C_sealed - M) % L)) % L
    c = (y_val + T) % L
    z = (C1 + c * C0) % L

    print(f"[*] Submitting computed z to /sign...")
    sign_resp = requests.post(f"{base_url}/sign", json={"z": str(z)})
    print(f"[+] Response: {sign_resp.text}", flush=True)

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print(f"Usage: python {sys.argv[0]} <target_ip>")
        sys.exit(1)
    solve(sys.argv[1])
